let currentLanguage = 'es';

function setLanguage(lang) {
    currentLanguage = lang;
    const elements = document.querySelectorAll('[data-i18n]');
    elements.forEach(el => {
        const key = el.getAttribute('data-i18n');
        if (translations[key] && translations[key][lang]) {
            el.innerHTML = translations[key][lang];
        }
    });

    // Translate inputs/textareas placeholder dynamically if they have data-i18n-placeholder
    const placeholders = document.querySelectorAll('[data-i18n-placeholder]');
    placeholders.forEach(el => {
        const key = el.getAttribute('data-i18n-placeholder');
        if (translations[key] && translations[key][lang]) {
            el.placeholder = translations[key][lang];
        }
    });

    // Translate href dynamically if they have data-i18n-href
    const hrefElements = document.querySelectorAll('[data-i18n-href]');
    hrefElements.forEach(el => {
        const key = el.getAttribute('data-i18n-href');
        if (translations[key] && translations[key][lang]) {
            el.href = translations[key][lang];
        }
    });

    // Toggle button styles
    document.querySelectorAll('.lang-btn').forEach(btn => {
        if(btn.getAttribute('data-lang') === lang) {
            btn.classList.add('font-bold', 'text-[#fdbc13]');
            btn.classList.remove('opacity-50');
        } else {
            btn.classList.remove('font-bold', 'text-[#fdbc13]');
            btn.classList.add('opacity-50');
        }
    });

    // Update active project modal if open
    if (typeof currentProjectData !== 'undefined' && currentProjectData) {
        const pKey = "proj_" + currentProjectData.folder.toLowerCase().replace(/[^a-z0-9]+/g, "_").replace(/^_+|_+$/g, "");
        
        const getTranslation = (key, defaultVal) => {
            if (translations[key] && translations[key][lang]) {
                return translations[key][lang];
            }
            return defaultVal;
        };

        const modalTitle = document.getElementById('modalProjectTitle');
        const modalClient = document.getElementById('modalProjectClient');
        const modalLocation = document.getElementById('modalProjectLocation');
        const modalDate = document.getElementById('modalProjectDate');
        const modalDesc = document.getElementById('modalProjectDesc');

        if (modalTitle) modalTitle.innerText = currentProjectData.folder;
        if (modalClient) modalClient.innerText = getTranslation(pKey + '_cliente', currentProjectData.meta.cliente);
        if (modalLocation) modalLocation.innerText = getTranslation(pKey + '_ubicacion', currentProjectData.meta.ubicacion);
        if (modalDate) modalDate.innerText = getTranslation(pKey + '_fecha', currentProjectData.meta.fecha);
        if (modalDesc) modalDesc.innerText = getTranslation(pKey + '_trabajos', currentProjectData.meta.trabajos);

        const modalConsultBtn = document.querySelector('#projectDetailModal a[href^="https://wa.me"]');
        if (modalConsultBtn) {
            const msg = lang === 'es' 
                ? `Hola, quisiera consultar sobre el proyecto ${currentProjectData.folder}`
                : `Hello, I would like to inquire about the project ${currentProjectData.folder}`;
            modalConsultBtn.href = `https://wa.me/584244117921?text=${encodeURIComponent(msg)}`;
        }
    }
    // Save language to localStorage for persistence
    localStorage.setItem('selectedLanguage', lang);
}

// Automatically load the saved language/theme or defaults
document.addEventListener('DOMContentLoaded', () => {
    const savedLang = localStorage.getItem('selectedLanguage') || 'es';
    setLanguage(savedLang);
    updateThemeIcon();
});

// Theme Management Functions
function toggleTheme() {
    const isDark = document.documentElement.classList.toggle('dark');
    localStorage.setItem('theme', isDark ? 'dark' : 'light');
    updateThemeIcon();
}

function updateThemeIcon() {
    const themeIcon = document.getElementById('theme-icon');
    if (themeIcon) {
        const isDark = document.documentElement.classList.contains('dark');
        themeIcon.innerText = isDark ? 'light_mode' : 'dark_mode';
    }
}

